   312→/// Helper trait to abstract over different [`Recovered<T>`] implementations.
   313→///
   314→/// Implemented for [`Recovered<T>`], `Recovered<&T>`, `&Recovered<T>`, `&Recovered<&T>`
   315→#[auto_impl::auto_impl(&)]
   316→pub trait RecoveredTx<T> {
   317→    /// Returns the transaction.
   318→    fn tx(&self) -> &T;
   319→
   320→    /// Returns the signer of the transaction.
   321→    fn signer(&self) -> &Address;
   322→}
   323→
   324→impl<T> RecoveredTx<T> for Recovered<&T> {
   325→    fn tx(&self) -> &T {
   326→        self.inner()
   327→    }
   328→
   329→    fn signer(&self) -> &Address {
   330→        self.signer_ref()
   331→    }
   332→}
   333→
   334→impl<T> RecoveredTx<T> for Recovered<T> {
   335→    fn tx(&self) -> &T {
   336→        self.inner()
   337→    }
   338→
   339→    fn signer(&self) -> &Address {
   340→        self.signer_ref()
   341→    }
   342→}
   343→
   344→impl<Tx, T: RecoveredTx<Tx>> RecoveredTx<Tx> for WithEncoded<T> {
   345→    fn tx(&self) -> &Tx {
   346→        self.1.tx()
   347→    }
   348→
   349→    fn signer(&self) -> &Address {
