    98→                .is_regolith_active_at_timestamp(evm.block().timestamp().saturating_to()),
    99→            evm,
   100→            system_caller: SystemCaller::new(spec.clone()),
   101→            spec,
   102→            receipt_builder,
   103→            receipts: Vec::new(),
   104→            gas_used: 0,
   105→            da_footprint_used: 0,
   106→            ctx,
   107→        }
   108→    }
   109→}
