   111→/// Custom errors that can occur during OP block execution.
   112→#[derive(Debug, thiserror::Error)]
   113→pub enum OpBlockExecutionError {
   114→    /// Failed to load cache account.
   115→    #[error("failed to load cache account")]
   116→    LoadCacheAccount,
   117→
   118→    /// Failed to get Jovian da footprint gas scalar from database.
   119→    #[error("failed to get da footprint gas scalar from database: {_0}")]
   120→    GetJovianDaFootprintScalar(Box<dyn core::error::Error + Send + Sync + 'static>),
   121→
   122→    /// Transaction DA footprint exceeds available block DA footprint.
   123→    #[error("transaction DA footprint exceeds available block DA footprint")]
   124→    TransactionDaFootprintAboveGasLimit {
   125→        /// The DA footprint of the transaction to execute.
   126→        transaction_da_footprint: u64,
   127→        /// The available block DA footprint.
   128→        available_block_da_footprint: u64,
   129→    },
   130→}
   131→
   132→impl<'db, DB, E, R, Spec> OpBlockExecutor<E, R, Spec>
   133→where
   134→    DB: Database + 'db,
   135→    E: Evm<
   136→        DB = &'db mut State<DB>,
   137→        Tx: FromRecoveredTx<R::Transaction> + FromTxWithEncoded<R::Transaction> + OpTxEnv,
   138→    >,
   139→    R: OpReceiptBuilder<Transaction: Transaction + Encodable2718, Receipt: TxReceipt>,
   140→    Spec: OpHardforks,
   141→{
   142→    fn get_jovian_da_footprint_scalar(&mut self) -> Result<u16, BlockExecutionError> {
   143→        let da_footprint_gas_scalar_slot = self
   144→            .evm
   145→            .db_mut()
   146→            .database
   147→            .storage(L1_BLOCK_CONTRACT, DA_FOOTPRINT_GAS_SCALAR_SLOT)
   148→            .map_err(|e| {
   149→                BlockExecutionError::other(OpBlockExecutionError::GetJovianDaFootprintScalar(
   150→                    Box::new(e),
   151→                ))
   152→            })?
   153→            .to_be_bytes::<32>();
   154→
   155→        // Extract the first 2 bytes directly as a u16 in big-endian format
   156→        let bytes = [
   157→            da_footprint_gas_scalar_slot[DA_FOOTPRINT_GAS_SCALAR_OFFSET],
   158→            da_footprint_gas_scalar_slot[DA_FOOTPRINT_GAS_SCALAR_OFFSET + 1],
   159→        ];
   160→        Ok(u16::from_be_bytes(bytes))
   161→    }
   162→
   163→    fn jovian_da_footprint_estimation(
   164→        &mut self,
   165→        tx: &impl ExecutableTx<Self>,
   166→    ) -> Result<u64, BlockExecutionError> {
   167→        // Try to use the enveloped tx if it exists, otherwise use the encoded 2718 bytes
   168→        let encoded = match tx.to_tx_env().encoded_bytes() {
   169→            Some(encoded) => estimate_tx_compressed_size(encoded),
   170→            None => estimate_tx_compressed_size(tx.tx().encoded_2718().as_ref()),
   171→        };
   172→
   173→        Ok(encoded
   174→            .saturating_div(1_000_000)
   175→            .saturating_mul(self.get_jovian_da_footprint_scalar()?.into()))
   176→    }
   177→}
