   179→impl<'db, DB, E, R, Spec> BlockExecutor for OpBlockExecutor<E, R, Spec>
   180→where
   181→    DB: Database + 'db,
   182→    E: Evm<
   183→        DB = &'db mut State<DB>,
   184→        Tx: FromRecoveredTx<R::Transaction> + FromTxWithEncoded<R::Transaction> + OpTxEnv,
   185→    >,
   186→    R: OpReceiptBuilder<Transaction: Transaction + Encodable2718, Receipt: TxReceipt>,
   187→    Spec: OpHardforks,
   188→{
   189→    type Transaction = R::Transaction;
   190→    type Receipt = R::Receipt;
   191→    type Evm = E;
   192→
   193→    fn apply_pre_execution_changes(&mut self) -> Result<(), BlockExecutionError> {
   194→        // Set state clear flag if the block is after the Spurious Dragon hardfork.
   195→        let state_clear_flag =
   196→            self.spec.is_spurious_dragon_active_at_block(self.evm.block().number().saturating_to());
   197→        self.evm.db_mut().set_state_clear_flag(state_clear_flag);
   198→
   199→        self.system_caller.apply_blockhashes_contract_call(self.ctx.parent_hash, &mut self.evm)?;
   200→        self.system_caller
   201→            .apply_beacon_root_contract_call(self.ctx.parent_beacon_block_root, &mut self.evm)?;
   202→
   203→        // Ensure that the create2deployer is force-deployed at the canyon transition. Optimism
   204→        // blocks will always have at least a single transaction in them (the L1 info transaction),
   205→        // so we can safely assume that this will always be triggered upon the transition and that
   206→        // the above check for empty blocks will never be hit on OP chains.
   207→        ensure_create2_deployer(
   208→            &self.spec,
   209→            self.evm.block().timestamp().saturating_to(),
   210→            self.evm.db_mut(),
   211→        )
   212→        .map_err(BlockExecutionError::other)?;
   213→
   214→        Ok(())
   215→    }
   216→
   217→    fn execute_transaction_without_commit(
   218→        &mut self,
   219→        tx: impl ExecutableTx<Self>,
   220→    ) -> Result<ResultAndState<<Self::Evm as Evm>::HaltReason>, BlockExecutionError> {
   221→        let is_deposit = tx.tx().ty() == DEPOSIT_TRANSACTION_TYPE;
   222→
   223→        // The sum of the transaction's gas limit, Tg, and the gas utilized in this block prior,
   224→        // must be no greater than the block's gasLimit.
   225→        let block_available_gas = self.evm.block().gas_limit() - self.gas_used;
   226→        if tx.tx().gas_limit() > block_available_gas && (self.is_regolith || !is_deposit) {
   227→            return Err(BlockValidationError::TransactionGasLimitMoreThanAvailableBlockGas {
   228→                transaction_gas_limit: tx.tx().gas_limit(),
   229→                block_available_gas,
   230→            }
   231→            .into());
   232→        }
   233→
   234→        if self.spec.is_jovian_active_at_timestamp(self.evm.block().timestamp().saturating_to())
   235→            && !is_deposit
   236→        {
   237→            let da_footprint_available = self.evm.block().gas_limit() - self.da_footprint_used;
   238→
   239→            let tx_da_footprint = self.jovian_da_footprint_estimation(&tx)?;
   240→
   241→            if tx_da_footprint > da_footprint_available {
   242→                return Err(BlockExecutionError::Validation(BlockValidationError::Other(
   243→                    Box::new(OpBlockExecutionError::TransactionDaFootprintAboveGasLimit {
   244→                        transaction_da_footprint: tx_da_footprint,
   245→                        available_block_da_footprint: da_footprint_available,
   246→                    }),
   247→                )));
   248→            }
   249→        }
   250→
   251→        // Execute transaction and return the result
   252→        self.evm.transact(&tx).map_err(|err| {
   253→            let hash = tx.tx().trie_hash();
   254→            BlockExecutionError::evm(err, hash)
   255→        })
   256→    }
   257→
   258→    fn commit_transaction(
   259→        &mut self,
   260→        output: ResultAndState<<Self::Evm as Evm>::HaltReason>,
   261→        tx: impl ExecutableTx<Self>,
   262→    ) -> Result<u64, BlockExecutionError> {
   263→        let ResultAndState { result, state } = output;
   264→        let is_deposit = tx.tx().ty() == DEPOSIT_TRANSACTION_TYPE;
   265→
   266→        // Fetch the depositor account from the database for the deposit nonce.
   267→        // Note that this *only* needs to be done post-regolith hardfork, as deposit nonces
   268→        // were not introduced in Bedrock. In addition, regular transactions don't have deposit
   269→        // nonces, so we don't need to touch the DB for those.
   270→        let depositor = (self.is_regolith && is_deposit)
   271→            .then(|| {
   272→                self.evm
   273→                    .db_mut()
   274→                    .load_cache_account(*tx.signer())
   275→                    .map(|acc| acc.account_info().unwrap_or_default())
   276→            })
   277→            .transpose()
   278→            .map_err(BlockExecutionError::other)?;
   279→
   280→        self.system_caller.on_state(StateChangeSource::Transaction(self.receipts.len()), &state);
   281→
   282→        let gas_used = result.gas_used();
   283→
   284→        // append gas used
   285→        self.gas_used += gas_used;
   286→
   287→        // Update DA footprint if Jovian is active
   288→        if self.spec.is_jovian_active_at_timestamp(self.evm.block().timestamp().saturating_to())
   289→            && !is_deposit
   290→        {
   291→            let tx_da_footprint = self.jovian_da_footprint_estimation(&tx)?;
   292→            // Add to DA footprint used
   293→            self.da_footprint_used = self.da_footprint_used.saturating_add(tx_da_footprint);
   294→        }
   295→
   296→        self.receipts.push(
   297→            match self.receipt_builder.build_receipt(ReceiptBuilderCtx {
   298→                tx: tx.tx(),
   299→                result,
   300→                cumulative_gas_used: self.gas_used,
   301→                evm: &self.evm,
   302→                state: &state,
   303→            }) {
   304→                Ok(receipt) => receipt,
   305→                Err(ctx) => {
   306→                    let receipt = alloy_consensus::Receipt {
   307→                        // Success flag was added in `EIP-658: Embedding transaction status code
   308→                        // in receipts`.
   309→                        status: Eip658Value::Eip658(ctx.result.is_success()),
   310→                        cumulative_gas_used: self.gas_used,
   311→                        logs: ctx.result.into_logs(),
   312→                    };
   313→
   314→                    self.receipt_builder.build_deposit_receipt(OpDepositReceipt {
   315→                        inner: receipt,
   316→                        deposit_nonce: depositor.map(|account| account.nonce),
   317→                        // The deposit receipt version was introduced in Canyon to indicate an
   318→                        // update to how receipt hashes should be computed
   319→                        // when set. The state transition process ensures
   320→                        // this is only set for post-Canyon deposit
   321→                        // transactions.
   322→                        deposit_receipt_version: (is_deposit
   323→                            && self.spec.is_canyon_active_at_timestamp(
   324→                                self.evm.block().timestamp().saturating_to(),
   325→                            ))
   326→                        .then_some(1),
   327→                    })
   328→                }
   329→            },
   330→        );
   331→
   332→        self.evm.db_mut().commit(state);
   333→
   334→        Ok(gas_used)
   335→    }
   336→
   337→    fn finish(
   338→        mut self,
   339→    ) -> Result<(Self::Evm, BlockExecutionResult<R::Receipt>), BlockExecutionError> {
   340→        let balance_increments =
   341→            post_block_balance_increments::<Header>(&self.spec, self.evm.block(), &[], None);
   342→        // increment balances
   343→        self.evm
   344→            .db_mut()
   345→            .increment_balances(balance_increments.clone())
   346→            .map_err(|_| BlockValidationError::IncrementBalanceFailed)?;
   347→        // call state hook with changes due to balance increments.
   348→        self.system_caller.try_on_state_with(|| {
   349→            balance_increment_state(&balance_increments, self.evm.db_mut()).map(|state| {
   350→                (
   351→                    StateChangeSource::PostBlock(StateChangePostBlockSource::BalanceIncrements),
   352→                    Cow::Owned(state),
   353→                )
   354→            })
   355→        })?;
   356→
   357→        let legacy_gas_used =
   358→            self.receipts.last().map(|r| r.cumulative_gas_used()).unwrap_or_default();
   359→
   360→        Ok((
   361→            self.evm,
   362→            BlockExecutionResult {
   363→                receipts: self.receipts,
   364→                requests: Default::default(),
   365→                gas_used: legacy_gas_used,
   366→                blob_gas_used: self.da_footprint_used,
   367→            },
   368→        ))
   369→    }
   370→
   371→    fn set_state_hook(&mut self, hook: Option<Box<dyn OnStateHook>>) {
   372→        self.system_caller.with_state_hook(hook);
   373→    }
   374→
   375→    fn evm_mut(&mut self) -> &mut Self::Evm {
   376→        &mut self.evm
   377→    }
   378→
   379→    fn evm(&self) -> &Self::Evm {
   380→        &self.evm
   381→    }
   382→}
