   384→/// Ethereum block executor factory.
   385→#[derive(Debug, Clone, Default, Copy)]
   386→pub struct OpBlockExecutorFactory<
   387→    R = OpAlloyReceiptBuilder,
   388→    Spec = OpChainHardforks,
   389→    EvmFactory = OpEvmFactory,
   390→> {
   391→    /// Receipt builder.
   392→    receipt_builder: R,
   393→    /// Chain specification.
   394→    spec: Spec,
   395→    /// EVM factory.
   396→    evm_factory: EvmFactory,
   397→}
