   399→impl<R, Spec, EvmFactory> OpBlockExecutorFactory<R, Spec, EvmFactory> {
   400→    /// Creates a new [`OpBlockExecutorFactory`] with the given spec, [`EvmFactory`], and
   401→    /// [`OpReceiptBuilder`].
   402→    pub const fn new(receipt_builder: R, spec: Spec, evm_factory: EvmFactory) -> Self {
   403→        Self { receipt_builder, spec, evm_factory }
   404→    }
   405→
   406→    /// Exposes the receipt builder.
   407→    pub const fn receipt_builder(&self) -> &R {
   408→        &self.receipt_builder
   409→    }
